// Determine reporting window: 'since last report'.
// Morning run  (08:30) -> window = previous 18:00 .. now
// Evening run  (18:00) -> window = today 08:30 .. now
const now = new Date();
const istOffsetMs = 5.5 * 60 * 60 * 1000;
const istNow = new Date(now.getTime() + istOffsetMs);
const hourIst = istNow.getUTCHours();

let windowStart;
let slot;
if (hourIst < 12) {
  // morning report: from yesterday 18:00 IST
  const y = new Date(istNow);
  y.setUTCDate(y.getUTCDate() - 1);
  y.setUTCHours(18, 0, 0, 0);
  windowStart = new Date(y.getTime() - istOffsetMs); // back to UTC
  slot = 'AM';
} else {
  // evening report: from today 08:30 IST
  const t = new Date(istNow);
  t.setUTCHours(8, 30, 0, 0);
  windowStart = new Date(t.getTime() - istOffsetMs);
  slot = 'PM';
}

return [{
  json: {
    slot,
    window_start: windowStart.toISOString(),
    window_end: now.toISOString(),
    ist_date: istNow.toISOString().slice(0, 10)
  }
}];

const win = $('Compute report window').first().json;
const s = $json;
function fmtAgo(iso) { if (!iso) return 'never'; const m = Math.floor((Date.now()-new Date(iso).getTime())/60000); if (m<60) return `${m}m ago`; const h=Math.floor(m/60); return h<24?`${h}h ago`:`${Math.floor(h/24)}d ago`; }
const tokenAgeH=s.fyers_token_updated?(Date.now()-new Date(s.fyers_token_updated).getTime())/3600000:999;
const captured=Number(s.signals_captured||0); const priced=Number(s.signals_priced||0);
const lines=[`📊 TradeBot Health — ${win.slot} ${win.ist_date}`,'',`${tokenAgeH<20?'✅':'❌'} Fyers token: ${s.fyers_token_updated?fmtAgo(s.fyers_token_updated):'MISSING'}`,`📥 Raw msgs (window): ${s.raw_msgs||0}`,`🎯 Signals captured: ${captured}`,`💰 Signals priced: ${priced}`,`🔎 Unresolved ticker: ${Number(s.unresolved_tickers||0)}`,`⚠️ Resolved but unpriced: ${Number(s.resolved_missing_price||0)} (marked unavailable: ${Number(s.quote_unavailable||0)})`,`📈 Avg slippage: ${s.avg_slippage_pct!=null?s.avg_slippage_pct+'%':'n/a'}`,`🤖 LLM errors: ${s.llm_errors_window||0}`,'',`Last signal: ${fmtAgo(s.last_signal_at)}`,`Window: ${win.window_start.slice(11,16)} → ${win.window_end.slice(11,16)} UTC`];
return [{json:{text:lines.join('\n'),slot:win.slot}}];
